// Bus de messages unidirectionnel — seul pont entre les modules
pub trait MessageHandler: Send + Sync {
    fn handle(&self, msg: &Message);
}

pub struct MessageBus {
    handlers: std::collections::HashMap<String, Vec<Box<dyn MessageHandler>>>,
}

impl MessageBus {
    pub fn emit(&self, msg: &Message) {
        if let Some(list) = self.handlers.get(&msg.msg_type) {
            for h in list { h.handle(msg); }
        }
    }
}
